-- Exámenes de validación REALES (28 sep 2026): A1.1–A1.3 y A2.1–A2.3, copiados de los
-- Google Forms de la cuenta del director (clave de respuestas y puntos tal como están en
-- Google). Reemplazan el examen de PRUEBA de A1.3 (se borra con sus envíos de prueba).
-- Notas: A2.2 tenía la lectura como imagen → transcrita a texto. A2.3 no está adjunto en el
-- DAY 16 de Classroom; se tomó el form "VALIDATION EXAM MODULE 6 LEVEL A2.3" del Drive del director.
begin;
delete from public.validation_exams where is_test;

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A1.1', 'VALIDATION EXAM MODULE 1 LEVEL A1.1',
  'This exam helps you check if you have reached the learning objectives of this course.
It does not affect your final result and does not determine if you move to the next level.
It is a tool to reflect on your progress and identify what you can improve.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":"Look at the questions and choose the correct answer.","passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. I ____ a student","options":["am","is","are"],"correct":[0],"points":5,"shuffle":true},{"type":"choice","id":"q2","text":"2. She _____ from Mexico","options":["am","is","are"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q3","text":"3. They _____ in the classroom","options":["am","is","are"],"correct":[2],"points":5,"shuffle":true},{"type":"choice","id":"q4","text":"4. We ____ friends","options":["am","is","are"],"correct":[2],"points":5,"shuffle":true},{"type":"choice","id":"q5","text":"5. He _____ not from Colombia.","options":["am","is","are"],"correct":[1],"points":5,"shuffle":true}]},{"title":"Vocabulary","instructions":"Look at the questions and choose the best answer.","passage":null,"youtube":null,"items":[{"type":"choice","id":"q6","text":"6. He is from Brazil. He is_____","options":["Brazil","Brazilian","British"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q7","text":"7. She is from Italy. She is ______","options":["Italy","Italian","Mexico"],"correct":[1],"points":5,"shuffle":true},{"type":"heading","text":"CHOOSE THE CORRECT ADJECTIVE"},{"type":"choice","id":"q8","text":"8. She is very ......","options":["friend","friendly","friendship"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q9","text":"9. He is very ......","options":["smart","smartly","smartest"],"correct":[0],"points":5,"shuffle":true},{"type":"choice","id":"q10","text":"10. Choose the correct sentence:","options":["He is tall and friendly","He tall is friendly","He is tall friendly is"],"correct":[0],"points":5,"shuffle":true}]},{"title":"Reading","instructions":"Read and choose the best answer.","passage":"About Laura\nMy name is Laura. I am from Colombia, and I am 20 years old. I am very happy because today is my first English class. I am a student, and I like learning new things. My teacher is Mr. Silva. He is from Brazil, and he is very friendly and patient. In my class, there are two new students. The first student is Tom. He is from Canada. He is tall and a little shy. He is 20 years old. He likes video games and music, but he doesn’t like homework. The second student is Maya. She is from Japan. She is small, smart, and very kind. She is 19 years old. She likes reading and taking pictures. She has a camera. We are all different, but we are happy to study together and learn English.","youtube":null,"items":[{"type":"choice","id":"q11","text":"11. Where is Laura from?","options":["Mexico","Colombia","Japan"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q12","text":"12. Is Mr. Silva friendly?","options":["Yes, he is","No, he isn't"],"correct":[0],"points":5,"shuffle":true},{"type":"choice","id":"q13","text":"13. Where is Tom from?","options":["Canada","Brazil","Spain"],"correct":[0],"points":5,"shuffle":true},{"type":"choice","id":"q14","text":"14. What does Tom NOT like?","options":["Music","Homework","Video games"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q15","text":"15. What does Maya have?","options":["A phone","A camera","A tablet"],"correct":[1],"points":5,"shuffle":true}]},{"title":"Listening","instructions":"Listen to the audio and choose the correct answer.","passage":null,"youtube":"fsq11qZi4po","items":[{"type":"choice","id":"q16","text":"16. What is his name?","options":["Luis","Carlos","Daniel"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q17","text":"17. Where is he from?","options":["Colombia","Mexico","Brazil"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q18","text":"18. How old is he?","options":["20","25","30"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q19","text":"19. What does he like?","options":["Homework","Music and video games","Sports"],"correct":[1],"points":5,"shuffle":true},{"type":"choice","id":"q20","text":"20. What does he NOT have?","options":["A phone","Headphones","A tablet"],"correct":[2],"points":5,"shuffle":true}]}]}$json$::jsonb,
  false, 'Google Form 16IS9aDOM2EPg-OSG20Jr0F_YpMSskFTxG0_b-jvZe_M (copiado el 28 sep 2026)')
on conflict (module_level) do update set title = excluded.title, intro = excluded.intro,
  content = excluded.content, is_test = false, source_note = excluded.source_note, updated_at = now();

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A1.2', 'VALIDATION EXAM MODULE 2 LEVEL A1.2',
  'This exam helps you check if you have reached the learning objectives of this course.
It does not affect your final result and does not determine if you move to the next level.
It is a tool to reflect on your progress and identify what you can improve. Below 70 means needs to practice.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. There ___ a small bedroom","options":["is","are","aren't"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q2","text":"2. I don't want ____ apples","options":["any","an","some"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q3","text":"3. My brother _____ TV all day","options":["watches","watch","watchs"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q4","text":"4. I think sugar is bad so I _____ eat candies","options":["never","usually","always"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q5","text":"5. My mother needs ______ banana","options":["a","an","some"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q6","text":"6. My father and my sister _____ to eat salchipapa","options":["like","likes","doesn't like"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q7","text":"7. Would you like ______ sugar?","options":["a","some","any"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q8","text":"8. I only have 4 days off so I ____: go to the gym","options":["usually","always","sometimes"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q9","text":"9. ____________ a bathroom upstairs?","options":["Is there","Are there","Is they"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q10","text":"10. Do you have ____ milk in the fridge?","options":["any","a","some"],"correct":[0],"points":3,"shuffle":true}]},{"title":"Vocabulary","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q11","text":"11. What activity is it?","image":"assets/examenes/a1-2-q11.jpg","options":["wake up","go to work","go to bed"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q12","text":"12. What activity is it?","image":"assets/examenes/a1-2-q12.jpg","options":["take a shower","get up","go to bed"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q13","text":"13. What activity is it?","image":"assets/examenes/a1-2-q13.jpg","options":["study","go home","go to college"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q14","text":"14. What place is it?","image":"assets/examenes/a1-2-q14.jpg","options":["bedroom","bathroom","living room"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q15","text":"15. What place is it?","image":"assets/examenes/a1-2-q15.jpg","options":["bedroom","wardrobe","dining room"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q16","text":"16. What is it?","image":"assets/examenes/a1-2-q16.jpg","options":["closet","shelf","table"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q17","text":"17. Countable or uncountable?","image":"assets/examenes/a1-2-q17.jpg","options":["countable","uncountable"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q18","text":"18. Countable or uncountable?","image":"assets/examenes/a1-2-q18.jpg","options":["countable","uncountable"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q19","text":"19. Countable or uncountable?","image":"assets/examenes/a1-2-q19.jpg","options":["countable","uncountable"],"correct":[0,1],"points":3,"shuffle":true},{"type":"choice","id":"q20","text":"20. Countable or uncountable?","image":"assets/examenes/a1-2-q20.jpg","options":["countable","uncountable"],"correct":[1],"points":3,"shuffle":true}]},{"title":"Reading","instructions":null,"passage":"My name is Andrés and I live with my sister. Our house is small, but it is comfortable. There is a kitchen, a living room, and two bedrooms. There are some chairs in the living room and a table next to the sofa.\nIn the morning, I wake up at 7:00 and my sister wakes up at 6:30. She prepares breakfast, but I don’t help her. There is some coffee and some bread on the table, but there isn’t any fruit today. I usually drink coffee, but my sister doesn’t drink coffee. She prefers juice.\nAfter breakfast, I go to work and she studies at home. In the afternoon, I eat lunch at a restaurant. There are some good options, but sometimes there isn’t any chicken, so I eat rice or a sandwich.\nIn the evening, we are at home. There is some food in the kitchen, but there aren’t any desserts. My sister cooks dinner and I help her sometimes. We usually eat together and talk about our day.\nAt night, I watch TV, but my sister doesn’t watch TV. She reads a book. We go to bed at 10:30 because we have a busy day.","youtube":null,"items":[{"type":"choice","id":"q21","text":"21. Why does Andrés sometimes eat rice or a sandwich instead of chicken?","options":["A. Because he doesn’t like chicken","B. Because there isn’t any chicken sometimes","C. Because he eats at home"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q22","text":"22. What is different about Andrés and his sister in the morning?","options":["A. They wake up at the same time","B. His sister wakes up earlier and prepares breakfast","C. Andrés prepares breakfast"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q23","text":"23. How do we know the house is small?","options":["A. Because Andrés says it is small but comfortable","B. Because there are many rooms","C. Because there is no kitchen"],"correct":[0],"points":4,"shuffle":true},{"type":"choice","id":"q24","text":"24. Why do Andrés and his sister go to bed at 10:30?","options":["A. Because they are tired and have a busy day","B. Because they watch TV","C. Because they eat late"],"correct":[0],"points":4,"shuffle":true},{"type":"choice","id":"q25","text":"25. What food is NOT available in their house in the evening?","options":["A. Bread","B. Desserts","C. Coffee"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Listening","instructions":null,"passage":null,"youtube":"NuZ5UbJwSbw","items":[{"type":"choice","id":"q26","text":"26. Why doesn’t Daniel drink coffee?","options":["A. Because there isn’t any coffee","B. Because he doesn’t like it","C. Because he is busy"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q27","text":"27. Why does Camila sometimes eat rice at the restaurant?","options":["A. Because she prefers rice","B. Because there isn’t any chicken sometimes","C. Because she eats at home"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q28","text":"28. What do Camila and Daniel do together in the evening?","options":["A. They watch TV together","B. They cook and eat together","C. They go out"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q29","text":"29. What can we say about the food in their house?","options":["A. There is a lot of food","B. There is some food, but not much","C. There isn’t any food"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q30","text":"30. Why do they go to bed at 10:30?","options":["A. Because they are bored","B. Because they have a busy day","C. Because they eat late"],"correct":[1],"points":4,"shuffle":true}]}]}$json$::jsonb,
  false, 'Google Form 1zckQKLYzp7albhF3BuM-nCXxqeIftJfITQ82Uyc2Mh0 (copiado el 28 sep 2026)')
on conflict (module_level) do update set title = excluded.title, intro = excluded.intro,
  content = excluded.content, is_test = false, source_note = excluded.source_note, updated_at = now();

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A1.3', 'VALIDATION EXAM MODULE 3 LEVEL A1.3',
  'This exam helps you check if you have reached the learning objectives of this course. It does not affect your final result and does not determine if you move to the next level. It is a tool to reflect on your progress and identify what you can improve.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":"Choose the correct answer","passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. She _____ to the market last Saturday","options":["go","goes","went"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q2","text":"2. They _____ not finish their homework yesterday.","options":["did","does","do"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q3","text":"3. _____ you see a good movie last weekend?","options":["Did","Does","Do"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q4","text":"4. My brother _____ dinner alone last night.","options":["make","maked","made"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q5","text":"5. We _____ a taxi because it was raining.","options":["taked","took","take"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q6","text":"6. I _____ very tired after work last Monday.","options":["am","was","were"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q7","text":"7. _____ your parents at home last night?","options":["Am","Was","Were"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q8","text":"8. She _____ at the office yesterday — she was sick.","options":["wasn't","weren't","isn't"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q9","text":"9. \"_____ the concert good last Friday?\" \"Yes, it _____.\"","options":["Was / was","Were / were","Was / were"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q10","text":"10. My little sister _____ ride a bike when she was four.","options":["can","could","couldn't"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q11","text":"11. _____ you speak English before you started this course?","options":["Can","Could","Did"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q12","text":"12. I _____ swim very well, but I _____ play tennis — I never learned.","options":["can / can't","can / couldn't","could / can't"],"correct":[1],"points":3,"shuffle":true},{"type":"heading","text":"Find the error in the sentence"},{"type":"choice","id":"q13","text":"13. Yesterday she buyed a new dress and went to a party.","options":["buyed","went","go"],"correct":[0],"points":4,"shuffle":true},{"type":"choice","id":"q14","text":"14. \"Could you to help me with this exercise, please?\"","options":["could","to help","with"],"correct":[1],"points":3,"shuffle":true}]},{"title":"Vocabulary","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q15","text":"15. What is the past form of the verb GO?","options":["goed","went","gone"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q16","text":"16. What is the past form of the verb BUY?","options":["buyed","bought","buyd"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q17","text":"17. What is the past form of the verb SEE?","options":["seed","seen","saw"],"correct":[2],"points":3,"shuffle":false},{"type":"choice","id":"q18","text":"18. Choose the correct time expression: \"I called her 10 minutes._______\"","options":["ago","last","yesterday"],"correct":[0],"points":3,"shuffle":false},{"type":"choice","id":"q19","text":"19. Choose the sentence that uses the time expression correctly.","options":["I ate pizza yesterday night.","I ate pizza last night.","I ate pizza the last night."],"correct":[0,1],"points":3,"shuffle":false},{"type":"choice","id":"q20","text":"20. Look at this situation: A person is playing the piano perfectly. What do we say about this person?","options":["She can play the piano.","She could play the piano.","She can't play the piano."],"correct":[0],"points":3,"shuffle":false},{"type":"choice","id":"q21","text":"21. Which sentence is a polite request?","options":["Could you explain this to me?","You explain this to me.","Explain this."],"correct":[0],"points":3,"shuffle":false}]},{"title":"Reading","instructions":null,"passage":"My name is Valentina and last weekend was very different from my usual routine.\nOn Saturday morning, I woke up late — it was already 9:30. I didn't go to the gym because\nI was really tired. Instead, I made breakfast at home and ate with my sister. We had eggs,\nbread and coffee. My sister didn't drink coffee because she doesn't like it. She had juice.\nIn the afternoon, we went to a market near our house. We bought some vegetables and fruit.\nThere was a small café next to the market, so we stopped there. I had a tea and my sister\nhad a hot chocolate. It was cold outside so the hot drinks were perfect.\nIn the evening, I watched a movie at home. My sister didn't watch TV — she read a book\ninstead. We went to bed at 11:00 because the next day was Sunday and we didn't have work.\nIt was a quiet weekend, but I really enjoyed it.","youtube":null,"items":[{"type":"choice","id":"q22","text":"22. Why didn't Valentina go to the gym on Saturday morning?","options":["Because the gym was closed","Because she was really tired","Because she went to the market"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q23","text":"23. What did Valentina and her sister do at the market?","options":["They bought vegetables and fruit","They had coffee and juice","They watched a movie"],"correct":[0],"points":4,"shuffle":true},{"type":"choice","id":"q24","text":"24. Why didn't Valentina's sister drink coffee","options":["Because there wasn't any coffee","Because she prefers tea","Because she doesn't like it"],"correct":[2],"points":4,"shuffle":true},{"type":"choice","id":"q25","text":"25. What did Valentina do in the evening?","options":["She read a book","She watched a movie at home","She went out with friends"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q26","text":"26. Why did they go to bed at 11:00?","options":["Because they were bored","Because the next day was Sunday and they didn't have work","Because they ate late"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Listening","instructions":null,"passage":null,"youtube":"mq93_iLc4_k","items":[{"type":"choice","id":"q27","text":"27. Where did Lucas go last Saturday?","options":["To the gym","To a park with his friends","To a restaurant"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q28","text":"28. Why couldn't Lucas play football when he was a child?","options":["Because he didn't like sports","Because he was sick","Because his neighborhood didn't have a field"],"correct":[2],"points":4,"shuffle":true},{"type":"choice","id":"q29","text":"29. What can Lucas do now that he couldn't do two years ago?","options":["He can speak English","He can cook","He can drive"],"correct":[0],"points":4,"shuffle":true},{"type":"choice","id":"q30","text":"30. What did Lucas ask his friend at the café?","options":["Can you pay for me?","Could you take a photo of us?","Can you come with me tomorrow?\""],"correct":[1],"points":4,"shuffle":true}]}]}$json$::jsonb,
  false, 'Google Form 1ln1fo9tqVZc-pdg2-MAkxpqxrsuzVF3Syg5zHScrV5A (copiado el 28 sep 2026)')
on conflict (module_level) do update set title = excluded.title, intro = excluded.intro,
  content = excluded.content, is_test = false, source_note = excluded.source_note, updated_at = now();

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A2.1', 'VALIDATION EXAM MODULE 4 LEVEL A2.1',
  'This exam helps you check if you have reached the learning objectives of this course. It does not affect your final result and does not determine if you move to the next level. It is a tool to reflect on your progress and identify what you can improve.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. _____ does she go to the supermarket? — Because it is cheaper than the mall.","options":["Where","Why","When"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q2","text":"2. _____ do they usually go to the Malecón?","options":["How","what","When"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q3","text":"3. A: _____ does your friend study English? B: At a language academy near her house.","options":["Why","Where","How"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q4","text":"4. A: _____ _____ you get to the city center? B: I take the Transmetro.","options":["How do","Where does","What do"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q5","text":"5. The Transmetro is _____ than a taxi in Barranquilla.","options":["more cheap","cheaper","cheapest"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q6","text":"6. The Malecón is _____ than my neighborhood park on weekends.","options":["more crowded","crowdeder","more crowdeder"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q7","text":"7. Barranquilla is _____ than Santa Marta.","options":["more big","biger","bigger"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q8","text":"8. She _____ visit her family in Cartagena this weekend.","options":["is going to","are going to","am going to"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q9","text":"9. They _____ eat fast food tonight. They prefer to cook at home.","options":["isn't going to","aren't going to","not going to"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q10","text":"10. _____ you _____ go to the Malecón on Sunday?","options":["Are / going to","is / going to","Do / going to"],"correct":[0],"points":3,"shuffle":true},{"type":"heading","text":"Find the mistake"},{"type":"choice","id":"q11","text":"11. My neighborhood is more bigger than the city center and more slow than the main road.","options":["more bigger → bigger / more slow → slower","more bigger → bigger / more slow is correct","The sentence is correct"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q12","text":"12. Andrés is going to visits the Malecón and she are going to stay home.","options":["visits → visit / are → is","is going to → goes to / are → is","The sentence is correct"],"correct":[0],"points":3,"shuffle":true}]},{"title":"Vocabulary","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q13","text":"13. You go here to save or withdraw money.","options":["Library","Bank","Hospital"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q14","text":"14. You go here when you are sick and need a doctor.","options":["Supermarket","Bus station","Hospital"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q15","text":"15. The pharmacy is _____ the supermarket and the library. — It is in the middle.","options":["next to","between","across from"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q16","text":"16. Go straight and _____ at the traffic light.\" — You need to change direction.","options":["across","go past","turn left"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q17","text":"17. The Malecón on a Sunday afternoon is full of people. It is very _____.","options":["quiet","busy","slow"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q18","text":"18. A local café near your house costs less than a restaurant downtown. The café is _____.","options":["expensive","difficult","cheap"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q19","text":"19. Which sentence uses a weekend plan correctly?","options":["I am going to the park is busy.","She is going to relax at home this Sunday.","They going to visit friends tomorrow."],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q20","text":"20. You use this WH word to ask about a reason.","options":["Where","When","Why"],"correct":[2],"points":3,"shuffle":true}]},{"title":"Reading","instructions":null,"passage":"My name is Santiago and I live in Barranquilla, in a neighborhood called El Prado. My neighborhood is quieter than the city center, but it is not far from important places. There is a Bancolombia branch two blocks from my house, and a small Éxito supermarketacross from it. I usually walk to both places because they are close.\nGetting around my neighborhood is easy. The streets are organized and there are clear signs. However, when I need to go to the bus station on Calle 17, I take the Transmetro because walking takes more than thirty minutes. The Transmetro is faster and cheaper than a taxi, so it is my favorite option.\nThis weekend, I am going to do something different. On Saturday, my sister and I are going to visit the Malecón del Río. She says it is more crowded than our park, but also more fun. We are not going to drive — we are going to take the Transmetro and walk along the river. On Sunday, I am going to stay home and clean the house. My parents are going to arrive from Bogotá, and I want everything to be ready.","youtube":null,"items":[{"type":"choice","id":"q21","text":"21. Why does Santiago walk to the bank and the supermarket instead of taking transport?","options":["Because he doesn't have money for transport","Because both places are close to his house","Because the Transmetro doesn't go there"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q22","text":"22. What can we infer about Santiago's relationship with the Malecón?","options":["He goes there every weekend","He has never been there before","He doesn't usually go there, but he is open to trying it"],"correct":[2],"points":4,"shuffle":true},{"type":"choice","id":"q23","text":"23. Why is Santiago going to clean the house on Sunday?","options":["Because the Malecón visit is on Sunday","Because his parents are coming from Bogotá and he wants to be prepared","Because his sister asked him to"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q24","text":"24. What does Santiago's choice of transport for the weekend tell us about him?","options":["He prefers expensive and fast options","He values practical and affordable options","He doesn't know how to drive"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q25","text":"25. Which statement best describes Santiago's weekend?","options":["He is going to spend both days outside with his family","He is going to mix a social outing with a day at home","He is going to rest and not do anything productive"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Listening","instructions":null,"passage":null,"youtube":"gvAUOnN4YqY","items":[{"type":"choice","id":"q26","text":"26. Why does Daniela prefer her neighborhood over the city center?","options":["Because it has more restaurants and shops","Because it is quieter and easier to get around","Because it is cheaper to live there"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q27","text":"27. What can we infer about Daniela's plans for Saturday?","options":["She wants to rest and stay indoors all day","She is excited about going somewhere more active than her usual routine","She is going to the Malecón because her friend told her to"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q28","text":"28. Daniela says the Malecón is \"more crowded but more alive\" than her park. What does she mean?","options":["The Malecón is dangerous and loud","The Malecón has more energy and things happening, even if there are more people","Her park is empty and boring all the time"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q29","text":"29. Based on what Daniela describes, what kind of person does she seem to be?","options":["Someone who avoids busy places and prefers to be alone","Someone who enjoys both calm routines and occasional social outings","Someone who is always looking for excitement and never stays home"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Writing","instructions":"PROMPT: Write a paragraph about your neighborhood and your plans for this weekend. Your paragraph must include: a topic sentence, three supporting sentences, and a concluding sentence. Use at least one comparative adjective and be going to.\nPARAGRAPH STRUCTURE:\n→ Topic sentence: Introduce your neighborhood.\n→ Supporting sentence 1: Describe a place near your home.\n→ Supporting sentence 2: Compare your neighborhood to another place.\n→ Supporting sentence 3: Describe one plan for this weekend using be going to.\n→ Concluding sentence: Close your paragraph with a final thought.","passage":null,"youtube":null,"items":[{"type":"text","id":"q30","text":"WRITE YOUR PARAGRAPH","points":4}]}]}$json$::jsonb,
  false, 'Google Form 1DnWOiQl7us8RO5jLO6cH5jOk2eXPf5-j0iIV_Iz3H-I (copiado el 28 sep 2026)')
on conflict (module_level) do update set title = excluded.title, intro = excluded.intro,
  content = excluded.content, is_test = false, source_note = excluded.source_note, updated_at = now();

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A2.2', 'VALIDATION EXAM MODULE 5 LEVEL A2.2',
  'This exam helps you check if you have reached the learning objectives of this course. It does not affect your final result and does not determine if you move to the next level. It is a tool to reflect on your progress and identify what you can improve.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. Andrés visited Bogotá, Medellín, and Cartagena. He says Cartagena had the best food, the friendliest people, and the most beautiful sunsets. What can we say about Cartagena?","options":["Cartagena was worse than the other cities","Cartagena was the most enjoyable city of the three for Andrés","Andrés liked Bogotá more than Cartagena"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q2","text":"2. Laura got 95/100 on her exam. Nobody in the class scored higher. Which sentence is correct?","options":["Laura got the most good grade in the class","Laura got the better grade in the class","Laura got the best grade in the class"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q3","text":"3. Two students are arguing about Barranquilla. One says: \"July is _____ month of the year here — it's almost impossible to go outside at noon.\" Which word completes the sentence correctly?","options":["the most hot","the hottest","the hotter"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q4","text":"4. Sofia arrived at her friend's house at 8 pm. The lights were off, soft music was playing, and something smelled delicious. What was her friend most likely doing?","options":["She was sleeping","She was cooking dinner","She was running in the park"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q5","text":"5. Miguel's boss called him at 3 pm. Miguel answered immediately and sounded alert and energetic. Which sentence is most likely true?","options":["He was sleeping when the phone rang","He wasn't sleeping — he was probably working","He were working and sleeping at the same time"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q6","text":"6. \"I was waiting for the Transmetro _____ I noticed my wallet was missing.\" Which word correctly connects these two actions?","options":["while","when","during"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q7","text":"7. Carlos says: \"_____ we were having dinner at the hotel, the electricity went out and the whole restaurant went dark.\" What does this sentence tell us about the timing?","options":["The electricity went out before dinner started","The electricity went out after dinner ended","The electricity went out in the middle of dinner"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q8","text":"8. Valentina has a high fever and her body aches all over. She is planning to go to work tomorrow. What is the most appropriate advice?","options":["She should go to work and drink coffee","She shouldn't go to work — she should rest and see a doctor","She should work from home and go running"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q9","text":"9. A traveler is at the airport for the first time and looks confused. He asks: \"_____ I check in online or at the counter?\" Which is the correct form?","options":["should","would","do"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q10","text":"10. The doctor told Pedro his stomachache was caused by eating too much junk food. What should the doctor have said?","options":["You should eat more fast food to feel better.","You shouldn't eat heavy food — your stomach needs to rest.","You should shouldn't eat anything at all this week.\""],"correct":[1],"points":3,"shuffle":true},{"type":"heading","text":"Q11 -12 — Find the error:"},{"type":"choice","id":"q11","text":"11. \"That was the most worst flight I have ever taken — the most longest delay and the most bad service.\"","options":["most worst → worst / most longest → longest / most bad → worst","most worst → most bad / most longest → longest","The sentence is correct"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q12","text":"12. \"She were talking on the phone while the taxi drived past the hotel entrance.\"","options":["were → was / drived → drove","were → was / while → when","talking → talked / drived → drove"],"correct":[0],"points":3,"shuffle":true}]},{"title":"Vocabulary","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q13","text":"13. You arrive at the airport and go to the desk to hand over your suitcase. The agent gives you a document that shows your seat number and boarding gate. What is this document called?","options":["Passport","Boarding pass","Reservation"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q14","text":"14. The screen at the airport shows that your flight to Bogotá is now leaving 3 hours later than scheduled. What is this situation called?","options":["Arrival","Customs","Delay"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q15","text":"15. Your colleague has been sneezing all morning, her nose is running, and she says she feels cold even though the office is warm. What does she most likely have?","options":["A sore throat","A cold","Back pain"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q16","text":"16. Diego woke up this morning and couldn't speak above a whisper. Every time he swallows water it feels like broken glass. What is his problem?","options":["A headache","A stomachache","A sore throat"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q17","text":"17. Carlos has visited many restaurants in Barranquilla. He says one place near El Prado has food that no other restaurant can match. Which sentence expresses this best?","options":["That restaurant has better food than others","That restaurant has the most delicious food in the area","That restaurant is more good than the others"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q18","text":"18. A friend is packing for a long international flight. She tends to get headaches on planes and often arrives dehydrated. What should she definitely bring?","options":["A boarding pass and a suitcase","Water and medicine for headaches","A passport and a heavy meal"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q19","text":"19. At 10 pm last Friday, the neighbors were making loud noises, music was playing, and people were laughing. What were they most likely doing?","options":["They were sleeping","They were having a party","They were studying"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q20","text":"20. A traveler is going to a very hot country for two weeks. She asks what she should pack. Which answer is the most useful?","options":["You should bring a heavy coat and boots.","You should pack light clothes, sunscreen, and stay hydrated.","You shouldn't bring anything — buy everything there."],"correct":[1],"points":3,"shuffle":true}]},{"title":"Reading","instructions":"Read the text carefully. The answers are not stated directly — think, connect, and infer.","passage":"Last month, I took what was supposed to be the most relaxing trip of my life. My name is Camila and I had planned everything perfectly: a flight to Santa Marta, three nights at a small hotel near the beach, and long days of doing absolutely nothing. I booked my reservation two months in advance and even arrived at the airport early.\n\nThings started going wrong almost immediately. While I was waiting at the gate, the screen showed a two-hour delay. I wasn't too worried at first, but then the delay became three hours, and then four. By the time I finally arrived in Santa Marta, it was almost midnight. I was exhausted and my back was hurting from sitting so long.\n\nThe next morning, I woke up with a sore throat and a low fever. I had been sitting under the air conditioning at the airport for hours. Instead of going to the beach, I spent most of the first day in my room. I ordered soup, drank a lot of water, and slept. By the second day, I felt a little better, but I still wasn't at my best.\n\nOn the last day, I finally made it to the beach. The water was the clearest I had ever seen and the view was the most beautiful thing I had experienced in years. Even after everything that went wrong, that last afternoon was worth the entire trip. Sometimes the worst journeys lead to the best moments.","youtube":null,"items":[{"type":"choice","id":"q21","text":"21. What does Camila's preparation — booking two months in advance and arriving early — tell us about her as a traveler?","options":["She is a spontaneous person who doesn't like to plan","She is an organized person who values being prepared","She travels every month and has a lot of experience"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q22","text":"22. Why did Camila get sick on her first morning in Santa Marta?","options":["She ate bad food on the plane","She spent many hours under strong air conditioning at the airport","She went swimming in cold water the night she arrived"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q23","text":"23. How does Camila feel about her trip overall, based on the final paragraph?","options":["She regrets going and would not recommend Santa Marta","Despite the difficulties, she found the trip worthwhile because of one perfect moment","She is angry about everything that went wrong and wants a refund"],"correct":[2],"points":4,"shuffle":true},{"type":"choice","id":"q24","text":"24. Camila says \"sometimes the worst journeys lead to the best moments.\" What does this tell us about her personality?","options":["She is pessimistic and sees problems in everything","She tends to find meaning and value even in difficult experiences","She thinks bad trips are always better than good ones"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q25","text":"25. Why does Camila describe the last afternoon as \"worth the entire trip\"?","options":["Because the hotel gave her a discount for the bad experience","Because the beauty of the beach compensated for everything that had gone wrong","Because she finally met interesting people on the last day"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Listening","instructions":null,"passage":null,"youtube":"ue7NiNeH0KQ","items":[{"type":"choice","id":"q26","text":"26. Based on what Diego says about his trip, what kind of traveler is he?","options":["Someone who panics when things go wrong and gives up easily","Someone who adapts to unexpected situations and keeps a positive attitude","Someone who only travels when everything is perfectly planned"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q27","text":"27. Diego mentions what he was doing when he realized something was wrong at the hotel. What does this suggest about the moment?","options":["He was prepared for the problem and knew how to solve it immediately","The problem caught him off guard during a normal, relaxed moment","He was already worried about the hotel before he arrived"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q28","text":"28. When Diego talks about his health during the trip, what can we infer about how he handled it?","options":["He ignored his symptoms and pushed through without resting","He took care of himself by resting and following basic advice","He went to the hospital immediately and missed the whole trip"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q29","text":"29. At the end of his story, Diego says he would go back to the same place. What does this tell us about his overall experience?","options":["He didn't enjoy the trip but wants to try again out of stubbornness","The positive parts of the trip were strong enough to outweigh the problems","He forgot about all the bad things that happened"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Writing","instructions":"PROMPT: Think about a moment during a trip — real or imaginary — when something unexpected happened. What were you doing when it occurred? How did it change your plans? What would you tell someone who goes through the same thing? Write a well-structured paragraph about that moment.\nYOUR PARAGRAPH MUST INCLUDE:\n→ Topic sentence: Introduce the trip and the unexpected moment.\n→ Supporting sentence 1: Describe what you were doing when it happened (past continuous).\n→ Supporting sentence 2: Explain how it affected your plans or how you felt.\n→ Supporting sentence 3: Use a superlative to describe something about the experience.\n→ Concluding sentence: Give one piece of advice using should / shouldn't.","passage":null,"youtube":null,"items":[{"type":"text","id":"q30","text":"WRITING","points":4}]}]}$json$::jsonb,
  false, 'Google Form 1_F5UEIep0uijbL3z6w4_iWV3mmy9O_a3eWk25SLc3LI (copiado el 28 sep 2026)')
on conflict (module_level) do update set title = excluded.title, intro = excluded.intro,
  content = excluded.content, is_test = false, source_note = excluded.source_note, updated_at = now();

insert into public.validation_exams (module_level, title, intro, content, is_test, source_note)
values ('A2.3', 'VALIDATION EXAM MODULE 6 LEVEL A2.3',
  'This exam helps you check if you have reached the learning objectives of this course.
It does not affect your final result and does not determine if you move to the next level.
It is a tool to reflect on your progress and identify what you can improve.',
  $json${"version":1,"sections":[{"title":"Grammar","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q1","text":"1. Your friend asks: \"Have you ever tried sushi?\" You ate it once at a food festival last year. Which answer is correct?","options":["Yes, I tried it last year at a food festival","Yes, I have tried it once","Yes, I have tried it last year"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q2","text":"2. Daniela wants to watch a new movie. Her friend asks if she has seen it. She hasn't watched it — she plans to watch it this weekend. Which sentence is correct?","options":["I didn't see it yet","I haven't seen it yet","I haven't seen it already"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q3","text":"3. Pablo calls his friend at 7:01 pm. His friend says: \"Perfect timing — I've just finished cooking. Come over!\" What does this tell us?","options":["The friend finished cooking a long time ago","The friend is still cooking and needs more time","The friend finished cooking moments before Pablo called"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q4","text":"4. Laura's mom asks her to book the bus tickets for their trip. Laura says: \"Don't worry, Mom — I've already done it.\" What does this mean?","options":["Laura is going to book the tickets later","Laura booked the tickets before her mom asked","Laura hasn't booked the tickets and needs help"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q5","text":"5. A teacher asks the class: \"Has anyone here ever lived in another city?\" Only two students raise their hands. What can we say about the rest of the class?","options":["They have all lived in other cities but don't want to say so","They have never lived outside their current city","They lived in other cities but came back"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q6","text":"6. At a new job, a manager tells you: \"You have to send a report every Friday — it's company policy. You don't have to wear a tie, but you must always be on time.\" Which statement is true?","options":["Wearing a tie and being on time are both optional","The report and being on time are obligations; the tie is not required","Everything mentioned is optional"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q7","text":"7. A sign at the entrance of a building says: \"You mustn't bring food inside.\" A different sign at a free museum says: \"You don't have to pay to enter.\" What is the difference?","options":["Both signs prohibit something different","The first is a prohibition; the second means entry is free — not obligatory to pay","Both signs mean the same thing — they are both rules you must follow"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q8","text":"8. Camila is applying for a passport. The form says: \"Applicants must provide a copy of their birth certificate.\" Camila doesn't have it with her. What is the problem?","options":["The birth certificate is optional — she can submit it later","Providing the birth certificate is a requirement — her application cannot proceed without it","She must only provide it if she plans to travel outside Colombia"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q9","text":"9. A student says: \"In my opinion, everyone should learn at least one foreign language.\" What is this student doing?","options":["Stating a fact that all people agree with","Sharing a personal view that others might agree or disagree with","Asking classmates what they think about languages"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q10","text":"10. Someone says: \"I think people spend too much time on their phones.\" You partly agree but also think phones are useful. Which response fits best?","options":["I couldn't agree more — phones are completely useless.","I see your point, but I also think phones help us stay connected and informed.","That's completely wrong. Phones are always good."],"correct":[1],"points":3,"shuffle":true},{"type":"heading","text":"FIND THE ERROR"},{"type":"choice","id":"q11","text":"11. \"She has never went abroad, but she have already applied for her passport and haven't received it yet.\"","options":["has never went → has never gone / she have → she has","has never went → never went / haven't → hasn't","The sentence is correct"],"correct":[0],"points":3,"shuffle":true},{"type":"choice","id":"q12","text":"12. \"You mustn't to use your phone during the exam, and students don't have to submitting late work.\"","options":["mustn't to → mustn't / submitting → submit","mustn't → don't have to / submitting is correct","The sentence is correct"],"correct":[0],"points":3,"shuffle":true}]},{"title":"Vocabulary","instructions":null,"passage":null,"youtube":null,"items":[{"type":"choice","id":"q13","text":"13. Miguel spent three weeks in Mexico last year. He had never left Colombia before. Which experience best describes what he did?","options":["He won a competition","He traveled abroad","He performed in public"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q14","text":"14. Andrea entered a national photography contest and got first place. The judges loved her work. Which experience does this describe?","options":["She volunteered for a cause","She tried exotic food","She won a competition"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q15","text":"15. You are waiting for a friend outside a restaurant. She texts you: \"I've _____ parked — I'll be there in 30 seconds!\" Which word fits?","options":["yet","already","just"],"correct":[2],"points":3,"shuffle":true},{"type":"choice","id":"q16","text":"16. Your teacher asks: \"Has everyone submitted the assignment?\" You haven't sent it — you plan to do it tonight. What do you say?","options":["I haven't submitted it just.","I haven't submitted it yet — I'll send it tonight.","I haven't already submitted it."],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q17","text":"17. You see a sign at a hospital showing a mobile phone with a red X. What does this sign mean?","options":["You don't have to bring your phone","You mustn't use your phone in this area","You must turn your phone on when you enter"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q18","text":"18. Your classmate says: \"I think learning English opens a lot of doors.\" You completely agree. Which response is most appropriate?","options":["I see your point, but I'm not sure about that.","I couldn't agree more — it really does make a difference.","Actually, I think that's not always true."],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q19","text":"19. Complete the sentence with the correct past participles: \"I have _____ to three countries, _____ two foreign languages, and _____ some amazing food along the way.\"","options":["went / learned / ate","been / learned / eaten","gone / learn / eating"],"correct":[1],"points":3,"shuffle":true},{"type":"choice","id":"q20","text":"20. A friend says: \"I believe working from home is always more productive than going to the office.\" You think it depends on the person. Which response is the most polite and accurate","options":["went / learned / ate","been / learned / eaten","gone / learn / eating"],"correct":[1],"points":3,"shuffle":true}]},{"title":"Reading","instructions":"Read the text carefully. Some answers require connecting two ideas — not just finding one sentence.","passage":"My name is Juliana and I am 29 years old. I was born in Barranquilla and I have lived here my whole life. But I have always wanted to see more of the world. I have studied English since I was twelve years old, and recently I have started taking French classes online too. I haven't traveled outside Colombia yet, but I have already applied for my passport. My goal is to visit at least two countries before I turn 32.\nAt work, I have to attend a team meeting every Monday — it is not optional. I mustn't share information about our clients with people outside the company. But I don't have to wear formal clothes because we work remotely. I think remote work is one of the best things that has happened in recent years, although I know some people prefer the office.\nIn terms of experiences, I have volunteered at a local school, and I have performed in public twice — both times singing at small events in my neighborhood. I haven't won any competition yet, but I have entered two. I believe that trying is always better than doing nothing at all.","youtube":null,"items":[{"type":"choice","id":"q21","text":"21. Juliana says she has applied for her passport but hasn't traveled yet. What does this tell us about her travel plans?","options":["She has changed her mind and doesn't want to travel anymore","She is preparing to travel — she has taken a real step toward her goal","She travels frequently and already has several stamps in her passport"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q22","text":"22. Juliana mentions three things about her workplace: a required meeting, a rule about client information, and no dress code. What do these three things together tell us about her company?","options":["The company controls every detail of employees' daily lives","The company has some clear rules but also gives employees flexibility in other areas","The company has no real rules since everyone works from home"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q23","text":"23. Juliana says remote work is one of the best things in recent years, but adds that some people prefer the office. What does this show?","options":["She is not sure about her own opinion","She shares her opinion clearly but recognizes that not everyone agrees","She actually prefers going to the office but won't say so"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q24","text":"24. Juliana has entered two competitions but hasn't won yet. She says: \"trying is always better than doing nothing at all.\" Why does she probably say this?","options":["Because she is angry about losing and wants to complain","Because she believes the experience of trying has value, even without winning","Because she plans to stop entering competitions after this"],"correct":[1],"points":4,"shuffle":true},{"type":"choice","id":"q25","text":"25. Based on everything Juliana describes — her studies, her passport, her volunteering, her competitions — what is the most accurate description of her?","options":["Someone who makes plans but never follows through","Someone who is actively working toward her goals in different areas of her life","Someone who is satisfied with her life and doesn't want anything to change"],"correct":[1],"points":4,"shuffle":true}]},{"title":"Listening","instructions":null,"passage":null,"youtube":"m9RlYKMjUVs","items":[{"type":"choice","id":"q26","text":"26. Camilo talks about an experience he has had. What does his reaction to it tell us?","options":["He did it once and didn't enjoy it at all","He is glad he tried it, even though it was difficult at first","He has done it many times and finds it boring now"],"correct":[1],"points":4,"shuffle":false},{"type":"choice","id":"q27","text":"27. When Camilo describes the rules at his workplace, what can we understand about his company?","options":["The company is very strict about everything, including what employees wear","Some rules are non-negotiable, but employees have freedom in other things","The company has no rules because everyone works remotely"],"correct":[1],"points":4,"shuffle":false},{"type":"choice","id":"q28","text":"28. Camilo gives his opinion on something he has observed. How does he express it?","options":["He states his opinion as a fact that no one can disagree with","He shares what he thinks clearly, but in a way that leaves room for other views","He avoids giving a clear opinion because he doesn't want to cause conflict"],"correct":[1],"points":4,"shuffle":false},{"type":"choice","id":"q29","text":"29. At the end, Camilo mentions something he hasn't done yet. What does this suggest?","options":["He has given up on his goals and doesn't plan to try anymore","He still has things he wants to do — his story isn't finished yet","He has already done everything he wanted and is looking back on his life"],"correct":[1],"points":4,"shuffle":false}]},{"title":"Writing","instructions":"Read the prompt carefully. Write from your own experience.\nPROMPT: Think of something you have done or tried for the first time — or something you haven't done yet but really want to do. Write a paragraph about it. Include a rule that is important in your daily life, and share your opinion about why trying new things matters.\nYOUR PARAGRAPH MUST INCLUDE:\n→ Topic sentence: Introduce the experience or goal.\n→ Supporting sentence 1: Use present perfect + ever / never / already / yet / just.\n→ Supporting sentence 2: Mention a rule in your life using must / mustn't / have to / don't have to.\n→ Supporting sentence 3: Give your opinion using I think / I believe / In my opinion + a reason.\n→ Concluding sentence: End with a final thought about the experience or goal.","passage":null,"youtube":null,"items":[{"type":"text","id":"q30","text":"WRITE HERE","points":4}]}]}$json$::jsonb,
